// Frontend/src/hooks/useMessages.js
import { useState, useEffect, useCallback } from 'react';

const API_URL = 'http://localhost:5000/api/messages';

export const useMessages = () => {
  const [conversations, setConversations] = useState([]);
  const [messages, setMessages] = useState([]);
  const [currentConversation, setCurrentConversation] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const token = localStorage.getItem('authToken');
  const headers = {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${token}`
  };

  // Récupérer toutes les conversations
  const fetchConversations = useCallback(async () => {
    try {
      setLoading(true);
      const response = await fetch(`${API_URL}/conversations`, {
        headers
      });

      const data = await response.json();

      if (data.success) {
        setConversations(data.conversations);
      } else {
        setError(data.message);
      }
    } catch (err) {
      console.error('Erreur fetchConversations:', err);
      setError('Erreur lors du chargement des conversations');
    } finally {
      setLoading(false);
    }
  }, []);

  // Récupérer ou créer une conversation
  const getOrCreateConversation = useCallback(async (otherUserId) => {
    try {
      setLoading(true);
      const response = await fetch(`${API_URL}/conversations/create`, {
        method: 'POST',
        headers,
        body: JSON.stringify({ otherUserId })
      });

      const data = await response.json();

      if (data.success) {
        setCurrentConversation(data.conversation);
        return data.conversation;
      } else {
        setError(data.message);
      }
    } catch (err) {
      console.error('Erreur getOrCreateConversation:', err);
      setError('Erreur lors de la création de la conversation');
    } finally {
      setLoading(false);
    }
  }, []);

  // Récupérer les messages d'une conversation
  const fetchMessages = useCallback(async (conversationId) => {
    try {
      setLoading(true);
      const response = await fetch(`${API_URL}/conversations/${conversationId}/messages`, {
        headers
      });

      const data = await response.json();

      if (data.success) {
        setMessages(data.messages);
        setCurrentConversation(data.conversation);
      } else {
        setError(data.message);
      }
    } catch (err) {
      console.error('Erreur fetchMessages:', err);
      setError('Erreur lors du chargement des messages');
    } finally {
      setLoading(false);
    }
  }, []);

  // Envoyer un message
  const sendMessage = useCallback(async (conversationId, content) => {
    try {
      const response = await fetch(`${API_URL}/messages`, {
        method: 'POST',
        headers,
        body: JSON.stringify({ conversationId, content })
      });

      const data = await response.json();

      if (data.success) {
        setMessages([...messages, data.message]);
        return data.message;
      } else {
        setError(data.message);
      }
    } catch (err) {
      console.error('Erreur sendMessage:', err);
      setError('Erreur lors de l\'envoi du message');
    }
  }, [messages]);

  // Supprimer un message
  const deleteMessage = useCallback(async (messageId) => {
    try {
      const response = await fetch(`${API_URL}/messages/${messageId}`, {
        method: 'DELETE',
        headers
      });

      const data = await response.json();

      if (data.success) {
        setMessages(messages.filter(msg => msg.id !== messageId));
        return true;
      } else {
        setError(data.message);
      }
    } catch (err) {
      console.error('Erreur deleteMessage:', err);
      setError('Erreur lors de la suppression du message');
    }
  }, [messages]);

  // Marquer un message comme lu
  const markAsRead = useCallback(async (messageId) => {
    try {
      const response = await fetch(`${API_URL}/messages/${messageId}/read`, {
        method: 'PUT',
        headers
      });

      const data = await response.json();

      if (data.success) {
        setMessages(messages.map(msg =>
          msg.id === messageId ? { ...msg, is_read: true } : msg
        ));
      } else {
        setError(data.message);
      }
    } catch (err) {
      console.error('Erreur markAsRead:', err);
      setError('Erreur lors du marquage du message');
    }
  }, [messages]);

  // Archiver une conversation
  const archiveConversation = useCallback(async (conversationId) => {
    try {
      const response = await fetch(`${API_URL}/conversations/${conversationId}/archive`, {
        method: 'PUT',
        headers
      });

      const data = await response.json();

      if (data.success) {
        setConversations(conversations.filter(conv => conv.id !== conversationId));
        if (currentConversation?.id === conversationId) {
          setCurrentConversation(null);
          setMessages([]);
        }
        return true;
      } else {
        setError(data.message);
      }
    } catch (err) {
      console.error('Erreur archiveConversation:', err);
      setError('Erreur lors de l\'archivage');
    }
  }, [conversations, currentConversation]);

  // Initialiser les conversations au montage
  useEffect(() => {
    if (token) {
      fetchConversations();
    }
  }, [token, fetchConversations]);

  return {
    conversations,
    messages,
    currentConversation,
    loading,
    error,
    fetchConversations,
    getOrCreateConversation,
    fetchMessages,
    sendMessage,
    deleteMessage,
    markAsRead,
    archiveConversation,
    setError,
    setMessages
  };
};

export default useMessages;
